templates.code:
name: {nombre}
on:
  {evento}:
    branches: [{rama}]
permissions:
  contents: read
jobs:
  {job}:
    runs-on: {runner}
    timeout-minutes: {minutos}
    steps:
      - uses: {dueño}/{acción}@{versión}
        with:
          {input}: {valor}
      - run: {comando}

    outputs:
      {salida}: ${{ steps.{paso}.outputs.{salida} }}
    steps:
      - id: {paso}
        run: echo "{salida}={valor}" >> "$GITHUB_OUTPUT"
# en un job con needs: [{job}] se lee ${{ needs.{job}.outputs.{salida} }}

- uses: actions/cache@v6
  with:
    path: {carpeta_cache}
    key: {so}-{herramienta}-${{ hashFiles('{archivo_lock}') }}
    restore-keys: |
      {so}-{herramienta}-

- if: failure()
  uses: actions/upload-artifact@v7
  with:
    name: {nombre}
    path: {ruta}
    retention-days: {días}

- name: {paso}
  env:
    {VARIABLE}: ${{ secrets.{SECRETO} }}
    {OTRA}: ${{ vars.{VARIABLE_CONFIG} }}
  run: {comando}

"Condition": {
  "StringEquals": {
    "token.actions.githubusercontent.com:aud": "sts.amazonaws.com",
    "token.actions.githubusercontent.com:sub": "repo:{org}/{repo}:ref:refs/heads/{rama}"
  }
}

- id: tag
  run: echo "tag=${GITHUB_SHA::7}" >> "$GITHUB_OUTPUT"
# después: ${{ steps.tag.outputs.tag }} → {tag}
